// frontend/src/api.js
const API_BASE = process.env.REACT_APP_API_BASE || ""; // use proxy in dev or set env

export async function queryArea(q) {
  const url = `${API_BASE}/api/query?q=${encodeURIComponent(q)}`;
  const res = await fetch(url);
  const json = await res.json();
  if (!res.ok) throw new Error(json.error || JSON.stringify(json));
  return json;
}

export async function listAreas() {
  const url = `${API_BASE}/api/areas/`;
  const response = await fetch(url);

if (!response.ok) {
    throw new Error(`Server error: ${response.status}`);
}

const text = await response.text();

try {
    return JSON.parse(text);
} catch (err) {
    console.error("Invalid JSON from backend:", text);
    throw new Error("Backend did not return valid JSON");
}

}

export async function uploadExcelFile(file) {
  const form = new FormData();
  form.append("file", file);
  const url = `${API_BASE}/api/upload/`;
  const response = await fetch(url);

if (!response.ok) {
    throw new Error(`Server error: ${response.status}`);
}

const text = await response.text();

try {
    return JSON.parse(text);
} catch (err) {
    console.error("Invalid JSON from backend:", text);
    throw new Error("Backend did not return valid JSON");
}

}
